import{_ as a,C as s,o as n,c as r,a2 as e,E as i}from"./chunks/framework.BxGh02fV.js";const m=JSON.parse('{"title":"Adopt an existing project","description":"","frontmatter":{"title":"Adopt an existing project"},"headers":[],"relativePath":"en/guide/adopt.md","filePath":"en/guide/adopt.md"}'),l={name:"en/guide/adopt.md"};function h(p,t,d,c,u,g){const o=s("Capture");return n(),r("div",null,[t[0]||(t[0]=e('<h1 id="adopt-an-existing-project" tabindex="-1">Adopt an existing project <a class="header-anchor" href="#adopt-an-existing-project" aria-label="Permalink to &quot;Adopt an existing project&quot;">​</a></h1><p>This assistant brings into Effortless a repository that already exists and has never been tracked by Effortless (a &quot;brownfield&quot; project). It lays the OPALE scaffold, groups the code and aligns the project with the current schema, in four steps.</p><p>Before you start, decide on the work mode and the code layout — especially if your repository must keep its structure or relies on shared sources: see <a href="/Effortless/en/guide/setup.html">Choosing your setup</a>.</p><h2 id="start-the-adoption" tabindex="-1">Start the adoption <a class="header-anchor" href="#start-the-adoption" aria-label="Permalink to &quot;Start the adoption&quot;">​</a></h2><p>In the picker, click <strong>Adopt an existing project</strong> and choose the project folder. The assistant then opens on that folder; its path is recalled under the title of each step.</p>',5)),i(o,{name:"assistant-reprise",alt:"The adoption assistant, Detect step: simulation, preview and Apply button"}),t[1]||(t[1]=e('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><ul><li><strong>At the top</strong>: four numbered steps and the line &quot;Adopt an existing project · Detect (1/4)&quot;, then a progress bar.</li><li><strong>In the middle</strong>: the step&#39;s title and explanation, its settings, then two buttons: <strong>Simulate (dry-run)</strong> and <strong>Apply</strong>.</li><li><strong>At the bottom</strong>: <strong>Back</strong> on the left; <strong>Close</strong> and <strong>Next</strong> on the right, <strong>Finish</strong> on the last step.</li></ul><h2 id="simulate-then-apply" tabindex="-1">Simulate, then apply <a class="header-anchor" href="#simulate-then-apply" aria-label="Permalink to &quot;Simulate, then apply&quot;">​</a></h2><p>Each step runs twice:</p><ol><li><strong>Simulate (dry-run)</strong> shows what would be done, without writing anything. The result shows in <strong>Preview (simulation)</strong>.</li><li><strong>Apply</strong> really runs the step. It stays greyed out until the simulation has succeeded; the screen reminds you: &quot;Simulate first to unlock execution.&quot; The result shows in <strong>Execution result</strong>, and the step is marked &quot;Step applied ✓&quot;.</li></ol><p><strong>Next</strong> only enables once the step is applied: no step can be skipped.</p><h2 id="the-four-steps" tabindex="-1">The four steps <a class="header-anchor" href="#the-four-steps" aria-label="Permalink to &quot;The four steps&quot;">​</a></h2><ol><li><strong>Detect</strong>: analyzes the project&#39;s stack and tree, then sets up the OPALE scaffold. The &quot;Force re-initialization&quot; box is for a folder that already holds an Effortless configuration: it keeps a <code>.bak</code> backup before redoing it.</li><li><strong>Plan</strong>: applies the relocation plan detected in the previous step. Read the simulation to see each move before running it.</li><li><strong>Group code</strong>: gathers the root code under <code>codebase/&lt;stack&gt;/</code>. First fill in the <strong>Target stack identifier</strong> (for instance <code>app</code>, <code>api</code>, <code>desktop</code>): without it, the buttons stay greyed out.</li><li><strong>Finalize</strong>: runs the migrations to align the project with Effortless&#39;s current schema.</li></ol><h2 id="finish" tabindex="-1">Finish <a class="header-anchor" href="#finish" aria-label="Permalink to &quot;Finish&quot;">​</a></h2><p>On the fourth step, <strong>Finish</strong> opens the project in a tab. <strong>Close</strong> leaves the assistant at any time and takes you back to the picker; steps already applied stay applied.</p><h2 id="tip" tabindex="-1">Tip <a class="header-anchor" href="#tip" aria-label="Permalink to &quot;Tip&quot;">​</a></h2><p>Work on a clean, committed repository: the <strong>Group code</strong> step moves files.</p><h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p>The same steps exist as MCP verbs, each with its simulation mode: <code>effortless_migrate_init</code>, <code>effortless_migrate_apply</code>, <code>effortless_codebase_relocate</code> and <code>effortless_migrate</code>.</p>',14))])}const _=a(l,[["render",h]]);export{m as __pageData,_ as default};
